  const totalSaved=relevant.filter(item=>item.type==='savings'||item.type==='transfer'&&fromSavings(item.toFundId)).reduce((sum,item)=>sum+Number(item.amount||0),0);
  const rows=relevant.map(item=>({id:item.id,date:item.date,label:item.type==='savings'||item.type==='transfer'&&fromSavings(item.toFundId)?'Saved':item.type==='expense'?'Spent':'Moved out',title:item.title,amount:item.amount})).sort((a,b)=>String(b.date||'').localeCompare(String(a.date||'')));
